def dispatches(events):
    actions = []
    for event in events:
        if event["status"] == "ready":
            for channel in event["channels"]:
                if channel == "email":
                    actions.append((event["id"], channel, "send"))
                elif channel == "sms":
                    actions.append((event["id"], channel, "send"))
        elif event["status"] == "blocked":
            for channel in event["channels"]:
                if channel == "email":
                    actions.append((event["id"], channel, "hold"))
                elif channel == "sms":
                    actions.append((event["id"], channel, "hold"))
    return actions

